package cn.zj.zjmarket.verification;
import cn.zj.zjmarket.ZjMarketApplication;
import cn.zj.zjmarket.domain.refund.model.Refund.Settings;
import cn.zj.zjmarket.domain.refund.service.RefundService;
import cn.zj.zjmarket.infrastructure.adapter.repository.RefundRepository;
import cn.zj.zjmarket.infrastructure.adapter.port.refund.SimulatedRefundChannel;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.boot.SpringApplication;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import javax.sql.DataSource;
import java.nio.file.*;
import java.util.*;
import static cn.zj.zjmarket.verification.ProductCommands.*;
/** Uses only this stage's freshly accepted actual A team, after the readiness owner stopped A. */
public final class ActualRefundCommands {
 public static int run(){try{check(env("B_DATABASE_SCOPE").equals("b02-test")&&env("B_DATABASE_USERNAME").equals("zj_market_b02_test_app"),"isolated B scope");var json=new ObjectMapper();Path work=Path.of(env("B_PAYMENT_WORK")),manifest=Path.of(env("B_REFUND_ACTUAL_MANIFEST")).toAbsolutePath().normalize();check(manifest.toString().replace('\\','/').matches("D:/Java/zj-market-b-05/target/b03-readiness/b053-[A-Za-z0-9-]+/reconciliation-restart.json"),"only fresh current-stage actual A fixture");var accepted=json.readTree(Files.readAllBytes(manifest.getParent().resolve("report.json")));check(accepted.path("status").asText().equals("PASSED")&&accepted.path("ownedPortsReleased").asBoolean(),"actual A reconciliation acceptance and provider cleanup passed");var original=json.readTree(Files.readAllBytes(manifest));var fixtures=json.readTree(Files.readAllBytes(manifest.getParent().resolve("fixtures.json")));String order=original.path("paidOrder").asText();
  try(var ctx=new SpringApplication(ZjMarketApplication.class).run("--server.port=0","--b.identity.enabled=false","--b.product.enabled=false","--b.inventory.enabled=false","--b.order.enabled=false","--b.trade.enabled=false","--b.payment.enabled=false","--b.trade.events-enabled=false","--b.trial.enabled=false","--b.sync.enabled=false","--b.infrastructure.database.enabled=true","--b.infrastructure.rpc.enabled=false","--b.infrastructure.mq.enabled=false","--b.refund.enabled=false")){
   var ds=ctx.getBean(DataSource.class);var db=new JdbcTemplate(ds);var t=new TransactionTemplate(new DataSourceTransactionManager(ds));t.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);var settings=Settings.defaults();var repo=new RefundRepository(ds,t,settings,"s01","c01");repo.validateSchema();var channel=new SimulatedRefundChannel(ds,t,settings);
   var f=db.queryForMap("SELECT * FROM b_refund WHERE order_id=?",order);String refund=f.get("refund_id").toString();check(f.get("user_id").equals(fixtures.path("users").path("USER").asText())&&f.get("team_id").equals(original.path("team").asText())&&f.get("funds_status").equals("NONE")&&f.get("eligibility_status").equals("ELIGIBLE"),"fresh actual A accepted payment eligibility, never historical obligations");String paidHash=db.queryForObject("SELECT success_hash FROM b_payment WHERE payment_id=?",String.class,f.get("payment_id"));String completionHash=db.queryForObject("SELECT request_hash FROM b_reconciliation_submission WHERE task_id=?",String.class,original.path("task").asText());repo.admit(refund);
   try(var service=new RefundService(repo,channel,settings)){service.recover(refund);service.recover(refund);}
   check(db.queryForObject("SELECT funds_status FROM b_refund WHERE refund_id=?",String.class,refund).equals("SUCCEEDED")&&db.queryForObject("SELECT COUNT(*) FROM b_sim_refund_attempt WHERE refund_id=? AND state='SUCCEEDED'",Long.class,refund)==1&&db.queryForObject("SELECT COUNT(*) FROM b_sim_refund WHERE refund_id=? AND refunded_amount=amount",Long.class,refund)==1,"actual A eligible obligation refunds once without A/RPC/MQ");
   check(paidHash.equals(db.queryForObject("SELECT success_hash FROM b_payment WHERE payment_id=?",String.class,f.get("payment_id")))&&completionHash.equals(original.path("hash").asText())&&db.queryForObject("SELECT state FROM b_inventory_reservation WHERE order_id=?",String.class,order).equals("HELD")&&db.queryForObject("SELECT COUNT(*) FROM b_purchase_guard WHERE active_order_id=?",Long.class,order)==1&&db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",Long.class,order)==0,"original payment/completion/HELD/guard retained until B-05.5");
   check(db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger l JOIN b_reconciliation_member m ON m.out_trade_no=l.order_id WHERE m.task_id=? AND l.kind='RELEASE'",Long.class,original.path("task").asText())==2&&db.queryForObject("SELECT fact_version FROM b_refund WHERE refund_id=?",Long.class,refund)==2,"two original unpaid closes and two frozen refund versions");check(db.queryForObject("SELECT COUNT(*) FROM b_trade_outbox WHERE payment_id=? AND event_type<>'PAYMENT_SUCCEEDED'",Long.class,f.get("payment_id"))==0,"refund MQ remains next stage");Files.writeString(work.resolve("actual.txt"),"status=PASSED\nactual-A-fresh-three-B-member-FAILED/complete-replay/eligible-payment=PASSED\nprovider-stopped/RPC-MQ-disabled/independent-refund/exactly-once=PASSED\noriginal-payment/completion/paid-HELD/guard/two-unpaid-RELEASE=PASSED\nfrozen-versions-PENDING-SUCCEEDED=PASSED\nrefundId="+refund+"\norderId="+order+"\n");return 0;
  }
 }catch(Exception e){try{Files.writeString(Path.of(env("B_PAYMENT_WORK")).resolve("failure-actual.txt"),e.toString()+"\n"+Arrays.toString(e.getStackTrace()));}catch(Exception ignored){}System.err.println("Actual refund verification failed: "+e.getClass().getSimpleName());return 1;}}
}
